// ---------- people ----------
Object.assign(GIVERS, {
  g_oma: { name: 'Oma Threll-Sixfinger', title: 'Speaker of the Keelmoot', model: 'n_oma' }, g_saye: { name: 'Doctor Ilse Saye', title: 'Xenologist · unfunded', model: 'n_saye' }, g_tarn: { name: 'Tarn Hobb', title: 'Broker of difficult cargo', model: 'n_tarn' },
  g_adey: { name: 'Commander Ruth Adeyemi', title: 'Republic survey frigate Plain Dealing', model: 'n_adey' }, g_osk: { name: 'Adjutant Osk Varnel', title: 'Imperial Office of Acquisition', model: 'n_osk' },
  oolo: { name: 'Oolo-of-Nine-Keels', title: 'Sessil pilot · between ships', model: 'n_oolo' }, wynn: { name: 'Archivist Wynn Okafor', title: 'Fleet historian · Republic', model: 'n_wynn' }, hekt: { name: 'Hekt', title: 'Yard breaker · indentured', model: 'n_hekt' },
});
Object.assign(TALK, {
  g_oma: { bio: "Oma Threll lost a finger to a cutting torch at nineteen and had a spare one grafted on the other hand at forty, out of spite. She has spoken for the Keelmoot's breakers for thirty years, which mostly means telling large organisations to wait their turn.",
    greet: ["Mind where you put your feet. That's a ship you're standing on. So's that. It's all ship, love, there's no ground here at all.", "Republic's got a frigate in orbit. Empire's got a man with a ledger. Syndicate's got the yard. And I've got a kettle. Guess which of us has been here longest."],
    topics: [{ q: 'What is this place?', a: ["Sixty ships came in here two thousand years back and stopped. Becalmed. Their sun had gone out behind them, the story goes, and they'd run as far as they could on what they'd saved of it.", "They weren't built, those hulls. They were grown, like shells. Leave two touching for a few centuries and they knit. So now it's one great reef of ship, and we live on it like barnacles. Speaking of which, don't call Oolo a barnacle. Oolo is sensitive."] },
      { q: 'Why does everyone want it?', a: ["Not the hulls. Hull-metal's lovely but there's lovelier. It's what's in the holds. Every ship's got a cask in its keel, sealed, warm to the touch, and when you crack one the light that comes out is the wrong colour for any lamp we make.", "Starlight, the Doctor says. Bottled. Sixty casks of somebody else's sun. I've cut ships for fifty years, Captain. I've never been afraid of a cargo before."] }] },
  g_saye: { bio: "Ilse Saye came to the Becalmed on a one-year grant to study the Thren. That was nine years ago. The grant has not been renewed, and she has not noticed.",
    greet: ["Oh! A person. Good. I've been talking to the reeds, and they only ever say one thing.", "Please don't open any pods. I say that to everyone. About a third of them listen."],
    topics: [{ q: 'Who were the Thren?', a: ["Are. Who are the Thren. They're asleep, about nine hundred to a ship, in pods along the keels. Three legs, four arms, no face to speak of. They sang to each other. The whole fleet is one instrument, and the flagship plays it.", "They ran from something that ate their star. They took what light they could carry and ran until the light got low. Then they lay down to wait for someone to come with more. Nobody did. We came with cutting torches instead. I do think about that."] },
      { q: 'What do the reeds say?', a: ["They're antennae. Grown ones. They've been repeating a single message outward for two thousand years. I finished the translation last spring and I rather wish I hadn't.", "It says: 'We have kept it safe. Come and take it back.' Not 'help'. Not 'we are here'. They aren't calling for rescue, Captain. They're calling to whoever it belongs to. I'd very much like to know who the Thren thought they'd borrowed a sun from."] }] },
  g_tarn: { bio: "Tarn Hobb brokers the sort of cargo that has two buyers and one of them an army. He is polite, punctual, and has been shot at by a better class of person than most.",
    greet: ["Captain. I heard a free ship had put down. I do hope you're not busy, because I am about to make you busy.", "I never lie to my captains. I do occasionally let them be surprised."], topics: [{ q: "What's the job?", a: ["The Syndicate's sold these sixty hulls twice. Once to the Republic, once to the Empire. Somebody is going to be very disappointed, and disappointed fleets shoot the nearest thing.", "The nearest thing is the Keelmoot. So you and I are going to find out which contract is real, quietly, before the fleets do it loudly."] }] },
  g_adey: { bio: "Ruth Adeyemi commands a survey frigate with four guns and a library. She was sent to the Becalmed to 'assess and secure' and has been arguing with her orders ever since.",
    greet: ["Welcome aboard, in a manner of speaking. The Plain Dealing's up there. I'm down here because the people worth talking to are.", "The Lantern Hall sent you? Good. I need someone who can't be court-martialled."], topics: [{ q: 'What are your orders?', a: ["To buy sixty hulls for the Senate, sight unseen, cargo intact. Signed by the Committee on Stellar Survey. You may know the committee. I gather its chairman sends hampers.", "Nobody will tell me what the cargo is for. I've been in the fleet twenty-two years. When nobody will tell you what it's for, it's for something you'd refuse to carry."] }] },
  g_osk: { bio: "Osk Varnel keeps the Empire's ledger at the Becalmed. He is not a soldier and not a Covenant man; he is an accountant, and he has noticed that the Veil-Lord's order for sixty hulls specifies no guns.",
    greet: ["Acolyte. Sit. You are the first Covenant person I've met who arrived without a shuttle and a headache for me.", "I count things. That is all I do. It is remarkable how much people fear a man who counts."], topics: [{ q: 'What does the Veil-Lord want with them?', a: ["Sixty hulls, no gun mounts, holds refitted to carry one sealed cask each at constant temperature. That is not a fleet. That is a delivery.", "I am not paid to wonder who it is being delivered to. I have wondered anyway, on my own time, and I sleep badly."] }] },
  oolo: { bio: "Oolo is a Sessil: a soft person in a hard shell, with one bright eye and a pilot's hands. Sessil pilots bond to a keel for life. Oolo has outlived eight ships and is not ready to talk about the ninth.",
    greet: ["You fly the little ugly one on the pad? Oolo likes it. It has been hit often and is still rude. A good keel.", "Eight ships. All dead of other people's flying. Oolo would like the ninth to die of old age, with Oolo in it."], topics: [] },
  wynn: { bio: "Wynn Okafor was sent to catalogue the Thren fleet for the Republic's archives. Having catalogued it, Wynn has formed strong views about who should be allowed anywhere near it, and the list is short.",
    greet: ["Do you know they've a word for 'ship' that also means 'promise'? I've been thinking about that all week.", "I am a historian. I'm supposed to arrive after things have been ruined. This is my first time being early."], topics: [] },
  hekt: { bio: "Hekt owes the Ochre Syndicate eleven years of labour for a debt his mother signed. He is very large, very patient, and has been keeping his own tally of what the yard owes him.",
    greet: ["You're Covenant. Don't care. You're not Syndicate. Care about that.", "I cut the hulls open. I see what's in the pods. Then they tell me I didn't. Eleven years of that left, on paper."], topics: [] },
});
Object.assign(LORE, {
  threnlog: { title: "The Flagship's Log", where: 'choirdeep', text: "It is not written. It is sung, on a loop, into the deck. Doctor Saye's rendering: 'Day one of the stillness. Light remaining: enough for sixty to sleep or one to fly. We choose that all sleep. We have kept what was lent. We call to the lenders. Day one of the stillness. Light remaining...' It has been day one for two thousand years." },
  twocontracts: { title: "Quill's Two Contracts", where: 'yarddeep', text: "Two bills of sale for the same sixty hulls, cargo intact. One is countersigned for the Senate Committee on Stellar Survey. One carries a Veil-Lord's seal. The delivery dates are a day apart. In the margin, in a neat hand: 'Deliver to whichever arrives second. The first will have softened them up.'" },
  openpod: { title: 'An Open Pod', where: 'hold', text: "The lid has been cut, not opened. Inside is the print of a tall, narrow body in soft grey lining, still faintly warm. Someone has scratched a tally mark on the rim: this is the forty-first pod the yard has emptied. There is no note of where its sleeper went." },
});

