const qx = (lvl, f) => Math.round(xpNeed(lvl) * f * .36), Z = { zone: 'grave' }, BEASTS = ['g_grazer', 'g_worm', 'g_ray'], PICKS = ['g_pick', 'g_pickg'], WAKE = ['g_wake', 'g_wakeg'], YARDL = ['g_yard', 'g_yardg', 'g_yardh'];
const lvl20 = () => (S.hero?.lvl || 1) >= 19;
QUESTS.push(
  { id: 'gy_1', ...Z, giver: 'g_oma', lvl: 15, name: 'Barnacle Rates', where: 'strand', xp: qx(15, .8), gold: 60, obj: { kill: BEASTS, n: 8, what: 'Defeat 8 Rust Grazers, Keel Worms or Void Rays on the Strand, north of the Keelmoot' },
    say: ["Everybody who lands here wants something off me, so I've a rule: first you do the Moot a turn. The Strand's crawling. Grazers scraping the good plate, worms in the keels, rays taking the washing.", "Put down 8 of them, any sort, and I'll know you're the kind that helps. Then you can ask me your questions. Tea's free either way, I'm not a monster."], done: ["Eight. And you wiped your boots. You'd be amazed how rare that is in a hero. Sit down, the kettle's on, ask me what you like."] },
  { id: 'gy_2', ...Z, giver: 'g_saye', lvl: 15, pre: 'gy_1', name: 'One Thing, Over and Over', where: 'strand', xp: qx(15, .8), gold: 60, obj: { inspect: 'g_reed', n: 6, what: 'Take recordings from 6 listening reeds on the Strand' },
    say: ["The reeds! You've seen them, the tall ones with the rings. They're transmitting. They have been since the fleet stopped. I've recordings from the east side but my knees don't do the Strand any more.", "Would you take this and hold it against 6 of them? Just hold it there until it clicks. If one of them sounds different from the others, I shall probably cry, so do warn me."], done: ["All six the same. Of course they are. 'We have kept it safe. Come and take it back.' Six more times. Thank you. I'm not crying, it's the oxide."] },
  { id: 'gy_3', ...Z, giver: 'g_oma', lvl: 16, pre: 'gy_1', name: 'Moot Dues', where: 'ribs', xp: qx(16, .8), gold: 70, obj: { kill: PICKS, n: 10, what: 'Defeat 10 Bonepicker Cutters or Guns in the Ribs' },
    say: ["The Bonepickers used to be ours. Good cutters, most of them. Then the big buyers turned up, and Mags worked out you could make more robbing a breaker than being one.", "They're camped all through the Ribs. Thin them by 10. I'm not asking you to enjoy it. I taught half of them to hold a torch."], done: ["Ten. That'll make the rest think. Thinking's never been their strong suit, but they do get there if you give them a reason."] },
  { id: 'gy_4', ...Z, giver: 'g_oma', lvl: 17, pre: 'gy_3', name: 'The Best Cutter We Ever Had', where: 'ribs', xp: qx(17, 1), gold: 90, gear: true, obj: { named: 'g_mags', n: 1, what: 'Defeat Mags Tolliver-Rune in the eastern Ribs' },
    say: ["Mags Tolliver-Rune. She could take a keel-plate off whole, not a mark on it. I was going to hand her the Moot when I got old. I got old and she'd already helped herself.", "She's in the east of the Ribs with her favourites. She won't come quietly. She never did anything quietly, it was half her charm."],
    done: ["So that's that.", "I'll tell the Moot she left. They'll know what I mean, and they'll let me say it."], choices: [{ t: "I'm sorry. She was yours.", reply: ['Oma Threll-Sixfinger', "She was. Thank you for knowing it. Most would've asked for the bounty first."], moral: 1 }, { t: 'What was the bounty, again?', reply: ['Oma Threll-Sixfinger', "Ha. There it is. Here, and a bit over, because you made me laugh on a bad day."], gold: 40 }] },
  { id: 'gy_5', ...Z, giver: 'g_saye', lvl: 17, pre: 'gy_2', name: 'Do Not Open the Pods', where: 'hold', xp: qx(17, .8), gold: 80, obj: { inspect: 'g_pod', n: 6, what: "Check the seals on 6 sleeper's pods in the Sleepers' Hold, far to the west" },
    say: ["Somebody is opening pods. I count them every month, and every month there are fewer sealed ones in the Hold. The yard says it's worms. Worms don't use cutting torches.", "Would you check 6 for me? If the seal ring's whole, they're still asleep. If it's been cut... well. Then tell me how many, and tell me gently."], done: ["Six sealed. Thank heavens. But you saw the open ones, didn't you? You've the look. Forty-one, by the tally on the rim. Forty-one people, and nobody will tell me where they went."] },
  { id: 'gy_6', ...Z, giver: 'g_saye', lvl: 18, pre: 'gy_5', name: 'Awake and Not Glad of It', where: 'hold', xp: qx(18, .8), gold: 90, obj: { kill: WAKE, n: 8, what: "Put 8 Wakened Thren or Choristers back to rest in the Sleepers' Hold" },
    say: ["When a pod's cut badly, the sleeper wakes. Two thousand years, and then a torch. They don't know where they are. They don't know the fleet stopped. They think you're the thing they ran from.", "I can't reach them. I've tried singing. I'm told I'm flat. 8 of them are loose in the Hold, and they'll hurt someone or themselves. Please. Kindly, if there's a kindly way."], done: ["Eight. I heard the note change each time. I'm going to believe that means they went back to sleep. Don't correct me."] },
  { id: 'gy_7', ...Z, giver: 'g_oma', lvl: 18, pre: 'gy_4', name: 'Paid by the Tonne', where: 'yard', xp: qx(18, .8), gold: 95, obj: { kill: YARDL, n: 10, what: 'Defeat 10 Yard Breakers, Marksmen or Heavies at the Breaking Yard, to the east' },
    say: ["The Syndicate's yard. They don't cut like we cut. We take what's dead and leave what's sleeping. They take it by the tonne and sort it after.", "I've asked them nicely. I've asked them officially. Now I'm asking you. Go and be 10 good reasons for them to slow down."], done: ["Ten. That's a shift short. Quill will be doing sums and not liking the answer. Good. I like her best when she's doing sums."] },
  { id: 'gy_8', ...Z, giver: 'g_saye', lvl: 19, pre: 'gy_6', name: 'The Tally', where: 'yarddeep', xp: qx(19, 1), gold: 110, gear: true, obj: { named: 'g_quill', n: 1, what: 'Defeat Yardmaster Oda Quill at the heart of the Breaking Yard' },
    say: ["Forty-one sleepers. I know where they went now. Hekt told me, the big one at the yard, and then asked me not to say he had. They were sold. Separately from the hulls. 'Biological cargo, misc.'", "Oda Quill signed for every one. I have never asked anyone to do what I'm about to ask you. I find I don't feel as bad about it as I expected."], done: ["Thank you. I'll write it up. Nobody will publish it. I'll write it up anyway, with all forty-one counted, so that somebody did."] },
  { id: 'gy_9', ...Z, giver: 'g_oma', lvl: 19, pre: 'gy_7', name: 'Loud on the Choir Deck', where: 'choir', xp: qx(19, .8), gold: 110, obj: { kill: WAKE, n: 10, what: 'Defeat 10 Wakened Thren or Choristers on the Choir Deck, at the far south' },
    say: ["The flagship's the south end of the reef. There's a deck on it, open to the sky, where the whole fleet's song comes together. The Doctor calls it the Choir.", "The yard's cutting has woken the crew up there, and woken them angry. Before anybody can talk to what runs that ship, 10 of them need settling. I'd come myself, but, knees."], done: ["Ten. I felt it from here, through the floor. The whole Moot went quiet for a second. Even the kettle."] },
  { id: 'gy_10', ...Z, giver: 'g_oma', turnTo: 'g_saye', lvl: 20, pre: 'gy_9', when: lvl20, name: 'Day One of the Stillness', where: 'choirdeep', xp: qx(20, 1.4), gold: 160, gear: true, obj: { named: 'g_cantor', n: 1, what: 'Face the Cantor on the Choir Deck, then tell Doctor Saye what it said' },
    say: ["The thing that runs the flagship. The Doctor calls it the Cantor. It's kept sixty crews asleep for two thousand years on one note, and it's started to lose the tune.", "If it goes, they all wake at once. Fifty thousand of them, frightened, on a reef with one town on it. Go and... I don't know what you do to a ship's mind. Quieten it. Bring some crew, this isn't one for doing alone."],
    done: [['Doctor Ilse Saye', "It spoke to you? In words? What did it... no. Sit. Tell me slowly."], ['Doctor Ilse Saye', "'The lenders are coming to collect.' Not the star-eaters. The ones who made them. The Thren didn't flee a monster, Captain. They ran off with something that belonged to somebody, and the somebody has sent the bailiffs."]],
    choices: [{ t: 'Then we give the light back.', reply: ['Doctor Ilse Saye', "To the people who put out suns to get it? ...And yet it is theirs. Oh, I do hate it when the kind answer and the right one have a fight."], moral: 1 }, { t: 'Then we keep it, and use it.', reply: ['Doctor Ilse Saye', "That's what the Thren said. Look how well they've slept on it."], moral: -1 }] },
  // the free captain: which contract is real
  { id: 'gs_1', story: true, ...Z, path: 'smuggler', giver: 'g_tarn', lvl: 15, name: 'Sold Twice', where: 'yard', xp: qx(15, .8), gold: 70, obj: { inspect: 'g_ledger', n: 5, what: 'Read 5 yard tally boxes around the Breaking Yard, to the east' },
    say: ["Here's the trouble, Captain. Quill's sold the fleet twice, and she'll have written down which sale she means to honour, because Syndicate people write everything down. It's their one weakness.", "The yard keeps tally boxes all round its edge. Read me 5. Don't steal them, just read them. I want her to go on thinking she's clever."], done: ["Five boxes, and every one's got two delivery columns. She means to honour both. Deliver to the second fleet after the first's been shot at. That's not a swindle, that's a war with an invoice."] },
  { id: 'gs_2', story: true, ...Z, path: 'smuggler', giver: 'g_tarn', lvl: 17, pre: 'gs_1', name: 'A Better Class of Enemy', where: 'ribs', xp: qx(17, .8), gold: 85, obj: { kill: PICKS, n: 8, what: 'Defeat 8 Bonepickers in the Ribs who are scouting for the Syndicate' },
    say: ["The Bonepickers have started carrying Syndicate rifles. New ones. Somebody's paying them to mark which hulls still have their casks.", "8 fewer scouts, and Quill's map goes a week out of date. A week is a long time in my trade. Fortunes have been made in a week. Mostly not by me, but I live in hope."], done: ["Eight. Lovely. You know, I've brokered for kings and for worse than kings, and it's a pleasure, a real pleasure, to work with somebody who simply does the thing."] },
  { id: 'gs_3', story: true, ...Z, path: 'smuggler', giver: 'g_tarn', turnTo: 'oolo', lvl: 19, pre: 'gs_2', when: lvl20, name: 'The Ninth Keel', where: 'town', xp: qx(19, .5), gold: 60, obj: { talk: true, what: 'Offer Oolo-of-Nine-Keels a berth aboard the Second Chance' },
    say: ["One more thing, and it's not a job. There's a Sessil pilot at the Moot, Oolo. Eight ships dead under them. The breakers say Oolo's bad luck. I say anyone who's walked away from eight wrecks is the opposite.", "You'll need a pilot who knows this reef when the fleets come. Ask. Be respectful about the shell."], done: [['Oolo-of-Nine-Keels', "The broker sent you. He thinks Oolo is lucky. Oolo is not lucky. Oolo is careful, and the others were not."], ['Oolo-of-Nine-Keels', "Yours has been hit and is still rude. Yes. Oolo will take your ninth keel, Captain. Do not die of flying. Oolo could not bear a tenth."]] },
  // the Republic: what the Senate is buying
  { id: 'gj_1', story: true, ...Z, path: 'justice', giver: 'g_adey', lvl: 15, name: 'Sight Unseen', where: 'yard', xp: qx(15, .8), gold: 70, obj: { inspect: 'g_ledger', n: 5, what: 'Read 5 yard tally boxes around the Breaking Yard, to the east' },
    say: ["My orders are to buy sixty hulls 'sight unseen'. In twenty-two years I have never bought so much as a ration crate sight unseen, and I don't mean to start with a fleet.", "The yard logs everything in tally boxes round its fence. Read 5 for me. You're Lantern Hall; if you're caught, it's a diplomatic incident. If I'm caught, it's my pension."], done: ["Casks. One per hull, kept warm. And a second buyer under a Veil-Lord's seal. So the Senate and the Empire want the same sixty bottles of somebody's sun, and neither has said why. I begin to dislike my orders very much."] },
  { id: 'gj_2', story: true, ...Z, path: 'justice', giver: 'g_adey', lvl: 17, pre: 'gj_1', name: 'Biological Cargo, Misc.', where: 'hold', xp: qx(17, .8), gold: 85, obj: { kill: WAKE, n: 8, what: "Put 8 Wakened Thren to rest in the Sleepers' Hold, and see what was done there" },
    say: ["There's a line on the Senate's contract I didn't understand. 'Biological cargo, misc., as available.' I asked the yard. They changed the subject. People only do that when the subject's a crime.", "Go to the Sleepers' Hold. The woken ones are a danger, so settle 8 of them. And while you're there, look at the pods. I want a witness who isn't in my chain of command."], done: ["Cut open. Forty-one of them. And my Senate has a standing order for more. I swore an oath to the Republic, novice. I'm trying to remember whether it mentioned the Committee on Stellar Survey. I don't believe it did."] },
  { id: 'gj_3', story: true, ...Z, path: 'justice', giver: 'g_adey', turnTo: 'wynn', lvl: 19, pre: 'gj_2', when: lvl20, name: 'Early, For Once', where: 'town', xp: qx(19, .5), gold: 60, obj: { talk: true, what: 'Ask Archivist Wynn Okafor to join your crew' },
    say: ["I can't act against my orders. I can, however, mislay a civilian. My fleet historian, Wynn Okafor, has catalogued every hull and every pod and is in a fair way to being arrested for saying so.", "Take Wynn with you. Somewhere the Committee can't send a hamper. I'll log it as 'transferred to Lantern Hall for consultation'. It's nearly true."], done: [['Archivist Wynn Okafor', "The Commander's mislaid me, has she? Good. I was about to do something brave and badly planned."], ['Archivist Wynn Okafor', "I have the full catalogue up here. Sixty ships, fifty-four thousand sleepers, by name where they left names. Somebody ought to be carrying it who intends to do something about it. I'll get my bag."]] },
  // the Empire: a delivery, not a fleet
  { id: 'gd_1', story: true, ...Z, path: 'dark', giver: 'g_osk', lvl: 15, name: 'The Honest Count', where: 'yard', xp: qx(15, .8), gold: 70, obj: { inspect: 'g_ledger', n: 5, what: 'Read 5 yard tally boxes around the Breaking Yard, to the east' },
    say: ["The Veil-Lord has paid for sixty hulls. I am to confirm sixty hulls. The Syndicate's figures and mine differ, and when figures differ, acolyte, somebody is lying, and it is never the arithmetic.", "Read me 5 of the yard's tally boxes. I would go, but they have seen my face, and it is a face people remember when they are hiding sums."], done: ["As I thought. A second buyer. The Republic. Quill means to let us fight for it and sell to the survivor. The Veil-Lord will want her head. I should like, first, to understand what it is we are fighting over."] },
  { id: 'gd_2', story: true, ...Z, path: 'dark', giver: 'g_osk', lvl: 17, pre: 'gd_1', name: 'No Gun Mounts', where: 'hold', xp: qx(17, .8), gold: 85, obj: { kill: WAKE, n: 8, what: "Defeat 8 Wakened Thren in the Sleepers' Hold and examine what they guard" },
    say: ["I have the refit orders. No guns. One cask per hull, held warm. Crew berths: none. Sixty ships that fly themselves somewhere and are not expected back.", "The sleepers in the Hold are said to guard the casks' tuning. Remove 8 of the woken ones and look. I want to know what the Veil-Lord is sending, and to whom. For the ledger."], done: ["The casks sing the same note as the reeds. 'Come and take it back.' So. The Empire is not building a fleet. It is paying a debt on someone else's behalf, and hoping to be thanked. I have balanced a great many books, acolyte. That one does not balance."],
    choices: [{ t: 'The Veil-Lord knows what he is doing.', reply: ['Adjutant Osk Varnel', "No doubt. I shall record your confidence. In pencil."], moral: -1 }, { t: 'Then perhaps the delivery should go astray.', reply: ['Adjutant Osk Varnel', "I did not hear that. I am, however, going to leave this manifest on the table and go for a long walk."], moral: 1 }] },
  { id: 'gd_3', story: true, ...Z, path: 'dark', giver: 'g_osk', turnTo: 'hekt', lvl: 19, pre: 'gd_2', when: lvl20, name: 'What the Yard Owes', where: 'town', xp: qx(19, .5), gold: 60, obj: { talk: true, what: 'Buy out Hekt’s indenture and offer him a berth' },
    say: ["There is a breaker at the yard, Hekt. Indentured. Eleven years remaining. He has seen inside every hull and has kept a tally the Syndicate would kill him for.", "I have purchased his contract out of the acquisitions budget, under 'tools, heavy'. He is at the Moot. He does not like the Covenant. Do not take it personally; I find it rather restful."], done: [['Hekt', "The counting man bought my paper. Says I'm yours now. I'm not anybody's. But I'll walk next to you, if you're walking at the yard."], ['Hekt', "Eleven years I'd have cut for them. I'll give you one, free, and we'll see. Where do I put the hammer?"]] },
);
CREW.oolo = { name: 'Oolo-of-Nine-Keels', pal: 0, flag: 'crew4', hi: "Oolo, aboard. This seat is too soft. Oolo will fix it. Do not touch the trim; Oolo has already fixed the trim.", pick: role => role === 'healer' ? 'elementalist' : 'binder' };
CREW.wynn = { name: 'Wynn Okafor', pal: 2, flag: 'jcrew4', hi: "Wynn Okafor, coming aboard, with a bag that is mostly paper. Where do you keep the library? ...I see. Where shall I put the library?", pick: role => role === 'healer' ? 'elementalist' : 'binder' };
CREW.hekt = { name: 'Hekt', pal: 2, flag: 'dcrew4', hi: "Hekt. Aboard. Low ceilings. I'll manage.", pick: role => role === 'dps' ? 'bladewarden' : 'aegis' };
X.turnin.push(q => { if (q.id === 'gs_3') X.recruit?.('oolo'); if (q.id === 'gj_3') X.recruit?.('wynn'); if (q.id === 'gd_3') X.recruit?.('hekt'); });
X.crewMount = (prev => (f, ...a) => prev?.(f, ...a))(X.crewMount);
